"""Migrated Meridian CRM opportunity_pipeline workflow."""

from __future__ import annotations

from typing import Any


def _value(record: dict, field: str) -> Any:
    """Return legacy field values, where missing fields are empty strings."""
    return record.get(field, "")


def _nvl(value: Any, default: Any) -> Any:
    """Legacy NVL: missing/empty values use the supplied default."""
    return default if value == "" or value is None else value


def _numeric(value: Any) -> float:
    """Legacy numeric coercion: empty strings compare as zero."""
    if value == "" or value is None:
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _can_qualify(record: dict) -> bool:
    return _numeric(_nvl(_value(record, "AMT"), 0)) > 0


def _has_close_date(record: dict) -> bool:
    # This is the explicit sentinel inequality defined by the legacy guard.
    return _value(record, "CLOSE_DT") != "00000000"


def _has_lost_reason(record: dict) -> bool:
    # Missing fields read as empty strings; only non-empty strings pass.
    return isinstance(_value(record, "LOST_RSN"), str) and _value(record, "LOST_RSN") != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire one opportunity_pipeline workflow event.

    The input record is never mutated. Transitions are tested in legacy XML
    document order.
    """
    updated = dict(record)

    if state == "P" and event == "qualify" and _can_qualify(record):
        updated["STAGE_PCT"] = "25"
        return {
            "state": "Q",
            "record": updated,
            "audits": ["OPP_QUAL"],
            "notifies": [],
            "matched": True,
        }

    if state == "Q" and event == "advance":
        updated["STAGE_PCT"] = "60"
        return {
            "state": "N",
            "record": updated,
            "audits": [],
            "notifies": [],
            "matched": True,
        }

    if state == "N" and event == "close_won" and _has_close_date(record):
        updated["STAGE_PCT"] = "100"
        return {
            "state": "W",
            "record": updated,
            "audits": ["OPP_WON"],
            "notifies": ["won_deal"],
            "matched": True,
        }

    if state == "P" and event == "close_lost" and _has_lost_reason(record):
        updated["STAGE_PCT"] = "0"
        return {
            "state": "L",
            "record": updated,
            "audits": ["OPP_LOST"],
            "notifies": [],
            "matched": True,
        }

    if state == "Q" and event == "close_lost" and _has_lost_reason(record):
        updated["STAGE_PCT"] = "0"
        return {
            "state": "L",
            "record": updated,
            "audits": ["OPP_LOST"],
            "notifies": [],
            "matched": True,
        }

    if state == "N" and event == "close_lost" and _has_lost_reason(record):
        updated["STAGE_PCT"] = "0"
        return {
            "state": "L",
            "record": updated,
            "audits": ["OPP_LOST"],
            "notifies": [],
            "matched": True,
        }

    return {
        "state": state,
        "record": updated,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
